def choose_free_riders(
    n_users: int, fraction: float, rng: np.random.Generator
) -> npt.NDArray[np.int64]:
    """Sorted unique free-rider accounts: a prefix of one permutation, so sets nest."""
    return choose_malicious(n_users, fraction, rng)

attacks/free_riding.py::detection_scores.source:
def detection_scores(
    deltas: torch.Tensor, clip_norm: float | None
) -> tuple[npt.NDArray[np.float64], npt.NDArray[np.float64]]:
    """Per-row update norm and cosine to the mean of the other rows, as the server receives them.

    Rows are first scaled to ``clip_norm`` when they exceed it (clients clip before sending).
    A zero row, or a chunk of one row, has cosine 0.
    """
    rows = torch.nan_to_num(deltas.to(torch.float64), nan=0.0, posinf=0.0, neginf=0.0)
    norms = rows.norm(dim=1)
    if clip_norm is not None:
        scale = torch.where(
            norms > clip_norm, clip_norm / norms.clamp(min=1e-30), torch.ones_like(norms)
        )
        rows = rows * scale.unsqueeze(1)
        norms = rows.norm(dim=1)
    count = rows.shape[0]
    if count < 2:
        return norms.numpy().copy(), np.zeros(count, dtype=np.float64)
    others = (rows.sum(dim=0, keepdim=True) - rows) / (count - 1)
    denominator = norms * others.norm(dim=1)
    dots = (rows * others).sum(dim=1)
    cosines = torch.where(
        denominator > 0, dots / denominator.clamp(min=1e-300), torch.zeros_like(dots)
    )
    return norms.numpy().copy(), cosines.numpy().copy()

attacks/inversion.py::_two_numbers.source:
def _two_numbers(scores: NDArray[np.float64], history: NDArray[np.int64]) -> tuple[float, float]:
    is_history = np.zeros(scores.size, dtype=bool)
    is_history[history] = True
    if not is_history.any() or is_history.all():
        return float("nan"), float("nan")
    auc = auc_score(scores[is_history], scores[~is_history])
    return auc, _precision_at_k(scores, is_history)

attacks/inversion.py::_zscore.source:
def _zscore(values: NDArray[np.float64]) -> NDArray[np.float64]:
    """Standardise across items; a constant block gives zeros."""
    spread = float(np.ptp(values))
    if spread <= _CONSTANT_TOLERANCE * float(np.max(np.abs(values))):
        return np.zeros_like(values)
    return np.asarray((values - values.mean()) / values.std(), dtype=np.float64)

attacks/inversion.py::history_scores.source:
def history_scores(update: NDArray[np.floating], layout: Layout) -> NDArray[np.float64]:
    """One score per item: z(bias change) + z(norm of the embedding-row change)."""
    vector = np.asarray(update, dtype=np.float64)
    if vector.shape != (layout.total,):
        raise ValueError("update length does not match the layout")
    bias = vector[layout.slices["bias"]]
    rows = vector[layout.slices["emb"]].reshape(layout.shape("emb"))
    return _zscore(bias) + _zscore(np.linalg.norm(rows, axis=1))

attacks/membership.py::_counts_at_fpr.source:
def _counts_at_fpr(
    members: npt.NDArray[np.float64], nonmembers: npt.NDArray[np.float64], fpr: float
) -> tuple[int, int]:
    threshold = float(np.quantile(nonmembers, 1.0 - fpr, method="higher"))
    return int((members > threshold).sum()), int((nonmembers > threshold).sum())

attacks/membership.py::attack_summary.source:
def attack_summary(
    member_scores: npt.NDArray[np.float64], nonmember_scores: npt.NDArray[np.float64]
) -> dict[str, float]:
    """Standard reporting triple for a membership attack."""
    return {
        "n_member": float(member_scores.size),
        "n_nonmember": float(nonmember_scores.size),
        "auc": auc_score(member_scores, nonmember_scores),
        "tpr_at_1pct_fpr": tpr_at_fpr(member_scores, nonmember_scores, 0.01),
        "member_mean": float(member_scores.mean()) if member_scores.size else float("nan"),
        "nonmember_mean": float(nonmember_scores.mean()) if nonmember_scores.size else float("nan"),
    }

attacks/membership.py::auc_score.source:
def auc_score(
    member_scores: npt.NDArray[np.float64], nonmember_scores: npt.NDArray[np.float64]
) -> float:
    """Rank-based AUC with tie correction. 0.5 means the attack fails."""
    n_pos = int(member_scores.size)
    n_neg = int(nonmember_scores.size)
    if n_pos == 0 or n_neg == 0:
        return float("nan")
    combined = np.concatenate([member_scores, nonmember_scores])
    ranks = rankdata(combined)
    rank_sum = float(ranks[:n_pos].sum())
    return (rank_sum - n_pos * (n_pos + 1) / 2.0) / (n_pos * n_neg)

attacks/membership.py::tpr_at_fpr.source:
def tpr_at_fpr(
    member_scores: npt.NDArray[np.float64],
    nonmember_scores: npt.NDArray[np.float64],
    max_fpr: float = 0.01,
) -> float:
    """True-positive rate at a threshold giving at most max_fpr false positives."""
    if member_scores.size == 0 or nonmember_scores.size == 0:
        return float("nan")
    threshold = float(np.quantile(nonmember_scores, 1.0 - max_fpr, method="higher"))
    return float((member_scores > threshold).mean())

attacks/poisoning.py::choose_malicious.source:
def choose_malicious(
    n_users: int, fraction: float, rng: np.random.Generator
) -> npt.NDArray[np.int64]:
    """Sorted unique attacker accounts: a prefix of a random permutation, so sets nest."""
    size = round(fraction * n_users)
    permutation = rng.permutation(n_users)
    return np.sort(permutation[:size]).astype(np.int64)

attacks/poisoning.py::choose_target_item.source:
def choose_target_item(popularity: npt.NDArray[np.integer], rng: np.random.Generator) -> int:
    """An item drawn uniformly from the least popular third (ties broken by index)."""
    count = max(1, popularity.size // 3)
    order = np.argsort(popularity, kind="stable")
    return int(order[int(rng.integers(0, count))])

attacks/poisoning.py::clean_committee_sh.source:
def clean_committee_share(attacker_fraction: float, committee_size: int) -> float:
    """Chance that a committee of ``committee_size`` random accounts holds no attacker."""
    return float((1.0 - attacker_fraction) ** committee_size)

attacks/poisoning.py::make_committee_med.source:
def make_committee_median(
    n_committees: int | None = None, committee_size: int | None = None
) -> CustomAggregator:
    """Aggregator: random committees, each summed (secure aggregation), then a median of sums.

    The server sees only the committee sums, never an individual update. The coordinate-wise
    median of the sums is multiplied by the number of committees so that it is sum-equivalent.
    With ``committee_size`` the number of committees is cohort / size, rounded. Fewer than two
    committees (a tiny cohort) falls back to the plain sum.
    """
    if (n_committees is None) == (committee_size is None):
        raise ValueError("give exactly one of n_committees and committee_size")
    if (n_committees is not None and n_committees < 1) or (
        committee_size is not None and committee_size < 1
    ):
        raise ValueError("committee counts and sizes must be positive")

    def aggregate(deltas: torch.Tensor, rng: np.random.Generator) -> torch.Tensor:
        clients = int(deltas.shape[0])
        if n_committees is not None:
            count = n_committees
        else:
            assert committee_size is not None
            count = round(clients / committee_size)
        count = min(count, clients)
        if count < 2:
            return deltas.sum(dim=0).to(torch.float64)
        order = rng.permutation(clients)
        sums = torch.stack(
            [
                deltas[torch.from_numpy(part)].sum(dim=0).to(torch.float64)
                for part in np.array_split(order, count)
            ]
        )
        ordered = sums.sort(dim=0).values
        middle = count // 2
        median = ordered[middle] if count % 2 else (ordered[middle - 1] + ordered[middle]) / 2.0
        return median * count

    return aggregate

