def usage() -> str:
    """Help text listing every command."""
    lines = ["usage: prism <command> [options]", "", "commands:"]
    lines += [f"  {name:<15} {summary}" for name, (_, summary) in COMMANDS.items()]
    lines += ["", "Run 'prism <command> --help' for a command's options."]
    return "\n".join(lines)

