def counts_from_card(card_path: Path) -> tuple[int, int]:
    """Read (n_users, n_items) from the committed dataset card."""
    import json

    card = json.loads(card_path.read_text(encoding="utf-8"))
    return int(card["users"]), int(card["items"])

