eval/baselines.py::_binary_matrix.source:
def _binary_matrix(train_items: Sequence[npt.NDArray[np.int64]], n_items: int) -> sparse.csr_matrix:
    rows: list[int] = []
    cols: list[int] = []
    for user, items in enumerate(train_items):
        rows.extend([user] * int(items.size))
        cols.extend(int(value) for value in items)
    data = np.ones(len(rows), dtype=np.float32)
    return sparse.csr_matrix(
        (data, (np.array(rows, dtype=np.int64), np.array(cols, dtype=np.int64))),
        shape=(len(train_items), n_items),
    )

eval/baselines.py::item_popularity.source:
def item_popularity(
    train_items: Sequence[npt.NDArray[np.int64]], n_items: int
) -> npt.NDArray[np.float32]:
    """Count distinct training users per item."""
    counts = np.zeros(n_items, dtype=np.int64)
    for items in train_items:
        if items.size:
            np.add.at(counts, items, 1)
    return counts.astype(np.float32)

eval/baselines.py::knn_score_fn.source:
def knn_score_fn(
    train_items: Sequence[npt.NDArray[np.int64]],
    n_items: int,
    neighbours: int = KNN_NEIGHBOURS,
) -> Callable[[npt.NDArray[np.int64]], npt.NDArray[np.float32]]:
    """Score = sum of similarities to the user's training items."""
    matrix = _binary_matrix(train_items, n_items)
    similarity = item_knn_similarity(train_items, n_items, neighbours)

    def score_fn(users: npt.NDArray[np.int64]) -> npt.NDArray[np.float32]:
        block = matrix[users] @ similarity
        return np.asarray(block.todense(), dtype=np.float32)

    return score_fn

eval/baselines.py::popularity_score_fn.source:
def popularity_score_fn(
    train_items: Sequence[npt.NDArray[np.int64]], n_items: int
) -> Callable[[npt.NDArray[np.int64]], npt.NDArray[np.float32]]:
    """Same popularity ranking for every user; this is the non-profiling mode."""
    popularity = item_popularity(train_items, n_items)

    def score_fn(users: npt.NDArray[np.int64]) -> npt.NDArray[np.float32]:
        return np.tile(popularity, (users.size, 1))

    return score_fn

eval/metrics.py::_gini.source:
def _gini(counts: npt.NDArray[np.int64]) -> float:
    """Gini coefficient of item exposure; 0 = perfectly equal."""
    values = np.sort(counts.astype(np.float64))
    total = values.sum()
    n = values.size
    if total == 0.0 or n == 0:
        return 0.0
    index = np.arange(1, n + 1, dtype=np.float64)
    return float((2.0 * np.sum(index * values)) / (n * total) - (n + 1.0) / n)

eval/stats.py::clopper_pearson.source:
def clopper_pearson(successes: int, trials: int, alpha: float = 0.05) -> tuple[float, float]:
    """Exact one-sided lower and upper confidence bounds, each at level alpha."""
    if trials < 0 or successes < 0 or successes > trials:
        raise ValueError("need 0 <= successes <= trials")
    if trials == 0:
        return 0.0, 1.0
    lower = (
        0.0 if successes == 0 else float(stats.beta.ppf(alpha, successes, trials - successes + 1))
    )
    upper = (
        1.0
        if successes == trials
        else float(stats.beta.ppf(1.0 - alpha, successes + 1, trials - successes))
    )
    return lower, upper

eval/stats.py::holm_adjust.source:
def holm_adjust(pvalues: list[float]) -> list[bool]:
    """Holm-Bonferroni step-down decisions at ALPHA."""
    m = len(pvalues)
    order = sorted(range(m), key=lambda i: pvalues[i])
    decisions = [False] * m
    for rank, index in enumerate(order):
        threshold = ALPHA / (m - rank)
        if pvalues[index] <= threshold:
            decisions[index] = True
        else:
            break
    return decisions

eval/stats.py::min_two_sided_sign_p.source:
def min_two_sided_sign_p(n: int) -> float:
    """Smallest possible two-sided sign-test p-value for n paired seeds."""
    return min(1.0, 2.0 * math.pow(0.5, n))

eval/stats.py::personalisation_retained.source:
def personalisation_retained(private: float, non_private: float, popularity: float) -> float:
    """Share of the gain over MostPopular that survives privacy (NaN if there is no gain)."""
    if non_private <= popularity:
        return math.nan
    return (private - popularity) / (non_private - popularity)

eval/stats.py::retention.source:
def retention(private: float, non_private: float) -> float:
    """Private metric as a fraction of the non-private one (NaN if that is zero)."""
    return private / non_private if non_private != 0.0 else math.nan

eval/stats.py::user_bootstrap_ci.source:
def user_bootstrap_ci(
    values: npt.NDArray[np.float64], draws: int = 1000, seed: int = 0
) -> tuple[float, float]:
    """Percentile bootstrap 95% CI for a mean over users; NaN entries (skipped users) are ignored."""
    kept = values[np.isfinite(values)]
    if kept.size == 0:
        return float("nan"), float("nan")
    rng = np.random.default_rng(seed)
    means = np.empty(draws, dtype=np.float64)
    for index in range(draws):
        means[index] = kept[rng.integers(0, kept.size, size=kept.size)].mean()
    return float(np.percentile(means, 2.5)), float(np.percentile(means, 97.5))

