def _summary(per_target: Scorer) -> dict[str, Any]:
    """Mean and 95% bootstrap interval of each recovery metric over targets."""
    result: dict[str, Any] = {}
    for key in METRICS:
        values = np.array([m[key] for m in per_target], dtype=np.float64)
        finite = values[np.isfinite(values)]
        low, high = user_bootstrap_ci(values)
        result[key] = {
            "mean": float(finite.mean()) if finite.size else float("nan"),
            "ci95": [low, high],
        }
    return result

fl/aggregate.py::ClipResult.source:
@dataclass(frozen=True)
class ClipResult:
    """Clipped updates, their norms before clipping, and how many rows were not finite."""

    clipped: torch.Tensor
    norms: torch.Tensor
    nonfinite: int

fl/aggregate.py::clip_rows.source:
def clip_rows(deltas: torch.Tensor, clip_norm: float | None) -> ClipResult:
    """Clip each row to ``clip_norm``. Rows containing NaN or infinity are replaced by zeros."""
    finite = torch.isfinite(deltas).all(dim=1)
    safe = torch.where(finite.unsqueeze(1), deltas, torch.zeros_like(deltas))
    norms = safe.norm(dim=1)
    if clip_norm is None:
        clipped = safe
    else:
        scale = torch.clamp(clip_norm / norms.clamp(min=1e-12), max=1.0)
        clipped = safe * scale.unsqueeze(1)
    return ClipResult(clipped, norms, int((~finite).sum()))

fl/aggregate.py::noisy_mean.source:
def noisy_mean(
    total: torch.Tensor,
    expected: float,
    noise_multiplier: float,
    clip_norm: float | None,
    rng: np.random.Generator,
) -> torch.Tensor:
    """Add N(0, (z*C)^2) noise once to the summed updates and divide by the expected cohort."""
    if noise_multiplier > 0.0:
        if clip_norm is None:
            raise ValueError("differential privacy noise requires a clipping norm")
        noise = rng.normal(0.0, noise_multiplier * clip_norm, size=total.shape[0])
        total = total + torch.from_numpy(noise)
    return total / max(expected, 1.0)

fl/aggregate.py::robust_total.source:
def robust_total(deltas: torch.Tensor, kind: AggregatorName, trim_fraction: float) -> torch.Tensor:
    """Sum-equivalent aggregate of a whole cohort: K times the (robust) per-coordinate mean."""
    count = deltas.shape[0]
    if kind == "sum":
        return deltas.sum(dim=0).to(torch.float64)
    if kind == "median":
        return (deltas.median(dim=0).values * count).to(torch.float64)
    if kind == "trimmed_mean":
        if not 0.0 <= trim_fraction < 0.5:
            raise ValueError("trim_fraction must be in [0, 0.5)")
        cut = int(np.floor(trim_fraction * count))
        ordered = deltas.sort(dim=0).values
        kept = ordered[cut : count - cut] if cut > 0 else ordered
        return (kept.mean(dim=0) * count).to(torch.float64)
    raise ValueError(f"unknown aggregator: {kind}")

fl/availability.py::_rank_fraction.source:
def _rank_fraction(values: npt.NDArray[np.integer]) -> npt.NDArray[np.float64]:
    """Rank (ties averaged) mapped linearly onto [0, 1]; the mean is exactly 0.5."""
    n = values.size
    if n <= 1:
        return np.full(n, 0.5)
    ranks = np.asarray(stats.rankdata(values, method="average"), dtype=np.float64)
    return (ranks - 1.0) / (n - 1.0)

fl/availability.py::availability_vector.source:
def availability_vector(
    scenario: Scenario,
    activity: npt.NDArray[np.integer],
    degree: npt.NDArray[np.integer],
    rng: np.random.Generator,
    mean: float = 0.5,
    floor: float = 0.05,
) -> npt.NDArray[np.float64]:
    """One availability probability per user, in [floor, 1] (exactly 1 for "always").

    The two correlated scenarios map the user's rank (ties averaged) linearly onto
    ``[floor, 2 * mean - floor]``, so the population mean is ``mean`` and the vector
    never exceeds 1. ``rng`` is reserved for future trace-based scenarios.
    """
    del rng
    n = activity.size
    if degree.size != n:
        raise ValueError("activity and degree must have one entry per user")
    if scenario == "always":
        return np.ones(n, dtype=np.float64)
    if scenario not in SCENARIOS:
        raise ValueError(f"unknown scenario: {scenario}")
    if not floor <= mean <= 1.0:
        raise ValueError("mean must lie in [floor, 1]")
    if scenario == "independent":
        return np.full(n, mean, dtype=np.float64)
    high = 2.0 * mean - floor
    if high > 1.0:
        raise ValueError("2 * mean - floor must not exceed 1")
    driver = activity if scenario == "activity" else degree
    return np.asarray(floor + (high - floor) * _rank_fraction(driver), dtype=np.float64)

fl/availability.py::group_means.source:
def group_means(
    per_user: npt.NDArray[np.float64], groups: npt.NDArray[np.int64], n_groups: int = 3
) -> list[float]:
    """Mean per group, ignoring NaN; a group with no finite value gives NaN."""
    means: list[float] = []
    for group in range(n_groups):
        values = per_user[(groups == group) & ~np.isnan(per_user)]
        means.append(float(values.mean()) if values.size else float("nan"))
    return means

fl/availability.py::groups_by_degree.source:
def groups_by_degree(degree: npt.NDArray[np.integer]) -> npt.NDArray[np.int64]:
    """0 = no friends, 1 = one to five friends, 2 = more than five."""
    return np.where(degree == 0, 0, np.where(degree <= LOW_DEGREE_MAX, 1, 2)).astype(np.int64)

fl/availability.py::trace_static.source:
def trace_static(
    shares: npt.NDArray[np.float64],
    devices: npt.NDArray[np.int64],
    floor: float = TRACE_FLOOR,
) -> npt.NDArray[np.float64]:
    """Per-user availability probability: the user's device active share, floored."""
    return np.maximum(np.asarray(shares, dtype=np.float64)[devices], floor)

fl/client.py::make_delta_fn.source:
def make_delta_fn(
    layout: Layout, base: torch.Tensor, config: ModelConfig, local_steps: int, local_lr: float
) -> DeltaFn:
    """Build ``f(flat, visible, target) -> deltas`` with one row of ``deltas`` per user."""
    gradient = grad(user_loss)

    def one_user(flat: torch.Tensor, visible: torch.Tensor, target: torch.Tensor) -> torch.Tensor:
        start = unflatten(flat, layout)
        params = start
        for step in range(local_steps):
            grads = gradient(params, base, visible[step], target[step], config)
            params = {name: params[name] - local_lr * grads[name] for name in layout.names}
        return flatten({name: params[name] - start[name] for name in layout.names}, layout)

    batched = vmap(one_user, in_dims=(None, 0, 0))

    def delta_fn(flat: torch.Tensor, visible: torch.Tensor, target: torch.Tensor) -> torch.Tensor:
        with torch.no_grad():
            result: torch.Tensor = batched(flat, visible, target)
        return result

    return delta_fn

