def expected_cohort(
    n_eligible: int, rate: float, availability: npt.NDArray[np.float64] | None = None
) -> float:
    """Expected cohort size: a public constant, used as the averaging divisor."""
    if availability is None:
        return rate * n_eligible
    return float(rate * availability.sum())

fl/sampling.py::poisson_cohort.source:
def poisson_cohort(
    rng: np.random.Generator,
    eligible: npt.NDArray[np.int64],
    rate: float,
    availability: npt.NDArray[np.float64] | None = None,
) -> npt.NDArray[np.int64]:
    """Draw one cohort. User ``eligible[k]`` joins with probability rate * availability[k].

    Exactly ``eligible.size`` uniform numbers are consumed whatever the outcome, so
    the sampling stream stays aligned between runs that differ only in the rate.
    """
    if not 0.0 < rate <= 1.0:
        raise ValueError("rate must be in (0, 1]")
    probability: float | npt.NDArray[np.float64] = rate
    if availability is not None:
        if availability.shape != eligible.shape:
            raise ValueError("availability must have one entry per eligible user")
        if availability.size and (availability.min() < 0.0 or availability.max() > 1.0):
            raise ValueError(
                "availability must lie in [0, 1]: it may lower the rate, never raise it"
            )
        probability = rate * availability
    draws = rng.random(eligible.size)
    return np.asarray(eligible[draws < probability], dtype=np.int64)

fl/secagg.py::FixedPoint.source:
@dataclass(frozen=True)
class FixedPoint:
    """Fixed-point codec mapping [-clip, clip] floats to two's-complement uint64 words."""

    clip_norm: float
    scale_bits: int = 32

    def encode(self, values: NDArray[np.floating]) -> NDArray[np.uint64]:
        """Round values to fixed point; raise ValueError if any is non-finite or beyond clip."""
        v = np.asarray(values, dtype=np.float64)
        if not np.all(np.isfinite(v)):
            raise ValueError("update contains NaN or infinite values")
        if v.size and float(np.max(np.abs(v))) > self.clip_norm * (1.0 + _GUARD):
            raise ValueError("update coordinate exceeds the clip norm")
        scaled = np.rint(v * (2.0**self.scale_bits / self.clip_norm)).astype(np.int64)
        return scaled.view(np.uint64)

    def decode_sum(self, total: NDArray[np.uint64]) -> NDArray[np.float64]:
        """Interpret words as signed two's complement and rescale to floats."""
        signed = np.ascontiguousarray(total, dtype=np.uint64).view(np.int64)
        return signed.astype(np.float64) * (self.clip_norm / 2.0**self.scale_bits)

