ledger/log.py::_parse.source:
def _parse(path: Path) -> _Parsed:
    """Read a ledger file strictly; every structural problem becomes an error string."""
    leaves: list[dict[str, Any]] = []
    checkpoints: list[tuple[int, dict[str, Any]]] = []
    errors: list[str] = []
    try:
        raw = path.read_bytes()
    except OSError as exc:
        return _Parsed([], [], [f"cannot read ledger: {exc}"])
    if raw and not raw.endswith(b"\n"):
        errors.append("file does not end with a newline (truncated write)")
    for n, chunk in enumerate(raw.split(b"\n")[:-1] if raw.endswith(b"\n") else raw.split(b"\n")):
        if not raw:
            break
        try:
            line = json.loads(chunk.decode("utf-8"))
        except (UnicodeDecodeError, ValueError):
            errors.append(f"line {n}: not valid UTF-8 JSON")
            continue
        if not isinstance(line, dict):
            errors.append(f"line {n}: not a JSON object")
            continue
        if _dumps(line).encode() != chunk:
            errors.append(f"line {n}: not in canonical line form")
            continue
        kind = line.get("type")
        if kind == "leaf":
            if set(line) != {"type", "index", "receipt"} or not isinstance(line["receipt"], dict):
                errors.append(f"line {n}: malformed leaf")
            elif line["index"] != len(leaves) or isinstance(line["index"], bool):
                errors.append(f"line {n}: leaf index {line['index']!r}, expected {len(leaves)}")
            else:
                leaves.append(line["receipt"])
        elif kind == "checkpoint":
            keys = {"type", "origin", "size", "root_hex", "signature_hex"}
            if set(line) != keys or not isinstance(line["origin"], str):
                errors.append(f"line {n}: malformed checkpoint")
            else:
                checkpoints.append((len(leaves), line))
        else:
            errors.append(f"line {n}: unknown line type {kind!r}")
    return _Parsed(leaves, checkpoints, errors)

ledger/log.py::verify_ledger.source:
def verify_ledger(path: Path, public_hex: str) -> VerifyReport:
    """Check line structure, leaf order, every checkpoint root and signature, and coverage."""
    parsed = _parse(path)
    errors = list(parsed.errors)
    leaf_bytes: list[bytes] = []
    for i, receipt in enumerate(parsed.leaves):
        try:
            leaf_bytes.append(canonical_bytes(receipt))
        except ValueError as exc:
            errors.append(f"leaf {i}: {exc}")
    covered = 0
    good = 0
    if len(leaf_bytes) == len(parsed.leaves):
        for count, cp in parsed.checkpoints:
            size = cp["size"]
            if isinstance(size, bool) or not isinstance(size, int) or size != count:
                errors.append(f"checkpoint size {size!r} does not match {count} leaves before it")
                continue
            if not _is_hex(cp["root_hex"], 64) or not _is_hex(cp["signature_hex"], 128):
                errors.append("checkpoint root or signature is not lowercase hex")
                continue
            root = merkle_root(leaf_bytes[:size])
            if cp["root_hex"] != root.hex():
                errors.append(f"checkpoint at size {size}: root does not match leaves")
                continue
            if not verify(public_hex, _note(cp["origin"], size, root), cp["signature_hex"]):
                errors.append(f"checkpoint at size {size}: bad signature")
                continue
            good += 1
            covered = size
    if len(parsed.leaves) != covered and not errors:
        errors.append(f"{len(parsed.leaves) - covered} leaves after the last checkpoint")
    return VerifyReport(not errors, covered, good, tuple(errors))

ledger/merkle.py::_path.source:
def _path(m: int, leaves: Sequence[bytes]) -> list[bytes]:
    n = len(leaves)
    if n == 1:
        return []
    k = _split(n)
    if m < k:
        return [*_path(m, leaves[:k]), _root(leaves[k:])]
    return [*_path(m - k, leaves[k:]), _root(leaves[:k])]

ledger/merkle.py::_root.source:
def _root(leaves: Sequence[bytes]) -> bytes:
    n = len(leaves)
    if n == 0:
        return hashlib.sha256(b"").digest()
    if n == 1:
        return leaf_hash(leaves[0])
    k = _split(n)
    return node_hash(_root(leaves[:k]), _root(leaves[k:]))

ledger/merkle.py::_split.source:
def _split(n: int) -> int:
    """Largest power of two strictly less than n (n >= 2)."""
    return 1 << ((n - 1).bit_length() - 1)

ledger/merkle.py::_subproof.source:
def _subproof(m: int, leaves: Sequence[bytes], complete: bool) -> list[bytes]:
    n = len(leaves)
    if m == n:
        return [] if complete else [_root(leaves)]
    k = _split(n)
    if m <= k:
        return [*_subproof(m, leaves[:k], complete), _root(leaves[k:])]
    return [*_subproof(m - k, leaves[k:], False), _root(leaves[:k])]

ledger/merkle.py::consistency_proof.source:
def consistency_proof(old_size: int, leaves: Sequence[bytes]) -> list[bytes]:
    """Return the proof that the first `old_size` leaves are a prefix of `leaves`."""
    if not 1 <= old_size <= len(leaves):
        raise ValueError("old_size must satisfy 1 <= old_size <= len(leaves)")
    return _subproof(old_size, leaves, True)

ledger/merkle.py::inclusion_proof.source:
def inclusion_proof(index: int, leaves: Sequence[bytes]) -> list[bytes]:
    """Return the audit path for leaf `index` in the tree over `leaves`."""
    if not 0 <= index < len(leaves):
        raise ValueError("leaf index out of range")
    return _path(index, leaves)

ledger/merkle.py::leaf_hash.source:
def leaf_hash(data: bytes) -> bytes:
    """Return SHA-256(0x00 || data)."""
    return hashlib.sha256(b"\x00" + data).digest()

ledger/merkle.py::merkle_root.source:
def merkle_root(leaves: Sequence[bytes]) -> bytes:
    """Return the Merkle tree hash of raw leaf entries (empty tree gives SHA-256 of b"")."""
    return _root(leaves)

ledger/merkle.py::node_hash.source:
def node_hash(left: bytes, right: bytes) -> bytes:
    """Return SHA-256(0x01 || left || right)."""
    return hashlib.sha256(b"\x01" + left + right).digest()

ledger/merkle.py::verify_consistency.source:
def verify_consistency(
    old_size: int, new_size: int, old_root: bytes, new_root: bytes, proof: Sequence[bytes]
) -> bool:
    """Check a consistency proof between two roots (RFC 9162 section 2.1.4.2)."""
    if old_size < 1 or old_size > new_size:
        return False
    if old_size == new_size:
        return not proof and old_root == new_root
    path = list(proof)
    if old_size & (old_size - 1) == 0:
        path.insert(0, old_root)
    if not path:
        return False
    fn, sn = old_size - 1, new_size - 1
    while fn & 1:
        fn >>= 1
        sn >>= 1
    fr = sr = path[0]
    for c in path[1:]:
        if sn == 0:
            return False
        if fn & 1 or fn == sn:
            fr = node_hash(c, fr)
            sr = node_hash(c, sr)
            if not fn & 1:
                while not (fn & 1) and fn != 0:
                    fn >>= 1
                    sn >>= 1
        else:
            sr = node_hash(sr, c)
        fn >>= 1
        sn >>= 1
    return sn == 0 and fr == old_root and sr == new_root

ledger/merkle.py::verify_inclusion.source:
def verify_inclusion(
    leaf: bytes, index: int, tree_size: int, proof: Sequence[bytes], root: bytes
) -> bool:
    """Check an inclusion proof for a raw leaf entry (RFC 9162 section 2.1.3.2)."""
    if not 0 <= index < tree_size:
        return False
    fn, sn = index, tree_size - 1
    r = leaf_hash(leaf)
    for p in proof:
        if sn == 0:
            return False
        if fn & 1 or fn == sn:
            r = node_hash(p, r)
            if not fn & 1:
                while not (fn & 1) and fn != 0:
                    fn >>= 1
                    sn >>= 1
        else:
            r = node_hash(r, p)
        fn >>= 1
        sn >>= 1
    return sn == 0 and r == root

ledger/receipts.py::_check_finite.source:
def _check_finite(obj: Any) -> None:
    if isinstance(obj, float) and not math.isfinite(obj):
        raise ValueError("non-finite number in receipt")
    if isinstance(obj, Mapping):
        for v in obj.values():
            _check_finite(v)
    elif isinstance(obj, list | tuple):
        for v in obj:
            _check_finite(v)

ledger/receipts.py::canonical_bytes.source:
def canonical_bytes(obj: Mapping[str, Any]) -> bytes:
    """Serialise a receipt to RFC 8785 canonical JSON bytes; NaN or infinity raises ValueError."""
    _check_finite(obj)
    try:
        return rfc8785.dumps(dict(obj))
    except (rfc8785.CanonicalizationError, TypeError) as exc:
        raise ValueError(f"receipt is not canonicalisable: {exc}") from exc

ledger/receipts.py::generate_key.source:
def generate_key() -> Ed25519PrivateKey:
    """Create a fresh Ed25519 private key."""
    return Ed25519PrivateKey.generate()

ledger/receipts.py::public_key_hex.source:
def public_key_hex(key: Ed25519PrivateKey) -> str:
    """Return the raw 32-byte public key as lowercase hex."""
    raw = key.public_key().public_bytes(serialization.Encoding.Raw, serialization.PublicFormat.Raw)
    return raw.hex()

ledger/receipts.py::sign.source:
def sign(key: Ed25519PrivateKey, payload: bytes) -> str:
    """Return the Ed25519 signature over `payload` as hex."""
    return key.sign(payload).hex()

ledger/receipts.py::verify.source:
def verify(public_hex: str, payload: bytes, signature_hex: str) -> bool:
    """Return True iff the signature is valid; malformed inputs give False, never an error."""
    try:
        Ed25519PublicKey.from_public_bytes(bytes.fromhex(public_hex)).verify(
            bytes.fromhex(signature_hex), payload
        )
    except (InvalidSignature, ValueError):
        return False
    return True

models/hybrid.py::Layout.source:
@dataclass(frozen=True)
class Layout:
    """Named blocks of the flat parameter vector, in storage order."""

    names: tuple[str, ...]
    shapes: tuple[tuple[int, ...], ...]

    @cached_property
    def sizes(self) -> tuple[int, ...]:
        return tuple(int(np.prod(shape)) for shape in self.shapes)

    @cached_property
    def total(self) -> int:
        return sum(self.sizes)

    @cached_property
    def slices(self) -> dict[str, slice]:
        result: dict[str, slice] = {}
        offset = 0
        for name, size in zip(self.names, self.sizes, strict=True):
            result[name] = slice(offset, offset + size)
            offset += size
        return result

    def shape(self, name: str) -> tuple[int, ...]:
        return self.shapes[self.names.index(name)]

