def make_layout(n_items: int, dim: int) -> Layout:
    """Layout for a catalogue of ``n_items`` and embedding width ``dim``."""
    if n_items < 1 or dim < 1:
        raise ValueError("n_items and dim must be positive")
    return Layout(("emb", "umap", "bias"), ((n_items, dim), (dim, dim), (n_items,)))

models/hybrid.py::unflatten.source:
def unflatten(flat: torch.Tensor, layout: Layout) -> dict[str, torch.Tensor]:
    """View the flat vector as named parameter tensors."""
    if flat.shape[-1] != layout.total:
        raise ValueError("flat vector size does not match the layout")
    return {name: flat[layout.slices[name]].reshape(layout.shape(name)) for name in layout.names}

privacy/accounting.py::_event.source:
def _event(sample_rate: float, noise_multiplier: float, rounds: int) -> Any:
    gaussian = dp_accounting.GaussianDpEvent(noise_multiplier)
    step = (
        gaussian
        if sample_rate >= 1.0
        else dp_accounting.PoissonSampledDpEvent(sample_rate, gaussian)
    )
    return dp_accounting.SelfComposedDpEvent(step, rounds)

privacy/accounting.py::_pld_rounds_withi.source:
def _pld_rounds_within(
    budget_epsilon: float, sample_rate: float, noise_multiplier: float, n_users: int, upper: int
) -> int:
    delta = delta_for(n_users)
    if pld_epsilon(sample_rate, noise_multiplier, 1, delta) > budget_epsilon:
        return 0
    low, high = 1, upper
    if pld_epsilon(sample_rate, noise_multiplier, upper, delta) <= budget_epsilon:
        return upper
    while high - low > 1:
        middle = (low + high) // 2
        if pld_epsilon(sample_rate, noise_multiplier, middle, delta) <= budget_epsilon:
            low = middle
        else:
            high = middle
    return low

privacy/accounting.py::_safe.source:
def _safe(function: Any, *args: Any) -> float:
    try:
        return float(function(*args))
    except Exception:  # an accountant that cannot handle a regime fails the gate, not the run
        return float("nan")

privacy/accounting.py::calibrate_noise.source:
def calibrate_noise(
    sample_rate: float, rounds: int, n_users: int, target_epsilon: float, tolerance: float = 0.01
) -> float:
    """Smallest noise multiplier (to about 1%) whose epsilon of record is at most the target."""
    if target_epsilon <= 0.0:
        raise ValueError("target_epsilon must be positive")
    delta = delta_for(n_users)
    low, high = CALIBRATION_LOW, CALIBRATION_HIGH
    if pld_epsilon(sample_rate, high, rounds, delta) > target_epsilon:
        raise ValueError("target epsilon is unreachable within the search range")
    while high / low > 1.0 + tolerance / 4.0:
        middle = math.sqrt(low * high)
        if pld_epsilon(sample_rate, middle, rounds, delta) <= target_epsilon:
            high = middle
        else:
            low = middle
    noise = high
    # PRV can sit slightly above PLD: nudge the noise up until the value of record fits.
    for _ in range(20):
        report = epsilon_report(sample_rate, noise, rounds, n_users)
        if report.gate_ok and report.of_record <= target_epsilon:
            return round(noise, 5)
        noise *= 1.0 + tolerance / 4.0
    raise ValueError("calibration did not converge to a gate-consistent noise multiplier")

privacy/accounting.py::check_gate.source:
def check_gate(prv: float, pld: float, rdp: float) -> tuple[bool, str]:
    """Apply the consistency gate to three epsilons."""
    values = (prv, pld, rdp)
    if not all(math.isfinite(value) and value >= 0.0 for value in values):
        return False, "an accountant returned a non-finite epsilon"
    tolerance = max(GATE_RELATIVE * max(prv, pld), GATE_ABSOLUTE)
    if abs(prv - pld) > tolerance:
        return False, f"PRV {prv:.4f} and PLD {pld:.4f} disagree by more than {tolerance:.4f}"
    if rdp < max(prv, pld) - RDP_SLACK:
        return False, f"RDP {rdp:.4f} is below the tighter accountants ({max(prv, pld):.4f})"
    return True, "ok"

privacy/accounting.py::delta_for.source:
def delta_for(n_users: int) -> float:
    """delta = 1 / (10 n)."""
    return target_delta(n_users)

privacy/accounting.py::pld_epsilon.source:
def pld_epsilon(sample_rate: float, noise_multiplier: float, rounds: int, delta: float) -> float:
    """Epsilon from the dp_accounting PLD accountant."""
    if noise_multiplier <= 0.0:
        raise ValueError("noise_multiplier must be positive")
    if not 0.0 < sample_rate <= 1.0:
        raise ValueError("sample_rate must be in (0, 1]")
    if rounds < 1:
        raise ValueError("rounds must be >= 1")
    accountant = pld.PLDAccountant()
    accountant.compose(_event(sample_rate, noise_multiplier, rounds))
    return float(accountant.get_epsilon(delta))

privacy/dp.py::calibrate_noise.source:
def calibrate_noise(sample_rate: float, rounds: int, delta: float, target_epsilon: float) -> float:
    """Smallest noise multiplier whose PRV epsilon is <= target (bisection)."""
    if target_epsilon <= 0.0:
        raise ValueError("target_epsilon must be positive")
    high = NOISE_SEARCH_HIGH
    if privacy_epsilon(sample_rate, high, rounds, delta) > target_epsilon:
        raise ValueError("target epsilon unreachable within search range")
    low = NOISE_SEARCH_LOW
    while high - low > NOISE_SEARCH_TOL:
        mid = (low + high) / 2.0
        if privacy_epsilon(sample_rate, mid, rounds, delta) <= target_epsilon:
            high = mid
        else:
            low = mid
    return round(high, 4)

privacy/dp.py::clip_l2.source:
def clip_l2(vector: npt.NDArray[np.float32], max_norm: float) -> npt.NDArray[np.float32]:
    """Scale a vector so its L2 norm is at most max_norm, preserving direction."""
    if max_norm <= 0.0:
        raise ValueError("max_norm must be positive")
    norm = float(np.linalg.norm(vector))
    if norm == 0.0 or norm <= max_norm:
        return vector.copy()
    return np.asarray(vector * (max_norm / norm), dtype=np.float32)

privacy/dp.py::privacy_epsilon.source:
def privacy_epsilon(
    sample_rate: float, noise_multiplier: float, rounds: int, delta: float, mechanism: str = "prv"
) -> float:
    """Compose `rounds` Poisson-subsampled Gaussian steps and return epsilon."""
    if noise_multiplier <= 0.0:
        return float("inf")
    if not 0.0 < sample_rate <= 1.0:
        raise ValueError("sample_rate must be in (0, 1]")
    if rounds < 1:
        raise ValueError("rounds must be >= 1")

    from opacus.accountants import PRVAccountant, RDPAccountant

    accountant: Any
    if mechanism == "prv":
        accountant = PRVAccountant()
    elif mechanism == "rdp":
        accountant = RDPAccountant()
    else:
        raise ValueError(f"unknown mechanism: {mechanism}")
    for _ in range(rounds):
        accountant.step(noise_multiplier=noise_multiplier, sample_rate=sample_rate)
    return float(accountant.get_epsilon(delta=delta))

privacy/dp.py::target_delta.source:
def target_delta(n_users: int) -> float:
    """delta <= 1 / (10 n), per roadmap section 8.2."""
    if n_users <= 0:
        raise ValueError("n_users must be positive")
    return 1.0 / (DEFAULT_DELTA_DIVISOR * n_users)

seeding.py::stream.source:
def stream(seed: int, name: str) -> np.random.Generator:
    """Return the generator for one named stream of a run seed."""
    if seed < 0:
        raise ValueError("seed must be non-negative")
    key = zlib.crc32(name.encode("utf-8"))
    return np.random.default_rng(np.random.SeedSequence(entropy=seed, spawn_key=(key,)))

seeding.py::streams.source:
def streams(seed: int, names: Sequence[str] = STREAM_NAMES) -> dict[str, np.random.Generator]:
    """Return one independent generator per name."""
    return {name: stream(seed, name) for name in names}
